/* SPEC-SUIYIN-ADMIN-054: current asrLexicon default view; existing local edits retained. */
'use strict';
(()=>{
 const A=window.Admin,V=window.AdminViews;
 if(A.route!=='asrLexicon')return;
 const tenants=new Set(['bzds','crrm','mengzhua','ruixi-kh-xiaowen','rxxz','yestar','yestar-bj','yestar-gz','yestar-hz','yestar-jx','yestar-sz','ykjl','yzhb']);
 if(!tenants.has(A.tenant))return;
 const previous=V.render,{node}=A,selected=new Set();let query={word:'',category:'',status:'',source:''},draft={...query},pageSize=20,observer;
 const paths={upload:'M8 11V2m-3 3 3-3 3 3M3 12v2h10v-2',plus:'M8 2v12M2 8h12',search:'M10.5 10.5 14 14M12 7A5 5 0 1 1 2 7a5 5 0 0 1 10 0Z',reset:'M13.7 6a6 6 0 1 0 .1 4M14 2v4h-4',edit:'M3 10 10.8 2.2l3 3L6 13H3v-3ZM9.5 3.5l3 3M2 15h12',trash:'M2 4h12M6 4V2h4v2M4 4v10h8V4M7 6v6M9 6v6'};
 function icon(name){const el=node('span','asr-icon');el.innerHTML='<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.1" stroke-linecap="round" stroke-linejoin="round"><path d="'+paths[name]+'"/></svg>';return el;}
 function btn(text,run,cls='',symbol){const el=node('button','asr-button '+cls);el.type='button';if(symbol)el.append(icon(symbol));el.append(node('span','',text));el.onclick=run;return el;}
 function unavailable(label){A.toast(label+'的展开页面本次尚未采集，暂保留入口。');}
 function table(){const t=A.getTable();if(!A.model.asrCurrentSource){if(A.tenant!=='yestar-sz')t.rows=t.rows.filter(r=>r.id.startsWith('local-'));else t.rows.forEach(r=>{if(r.cells[5]==='无补充备注')r.cells[5]='';});A.model.asrCurrentSource='2026-09-27';}return t;}
 function rows(){return table().rows.filter(r=>(!query.word||[r.cells[1],r.cells[2]].some(v=>v.includes(query.word)))&&(!query.category||r.cells[4].split(/[\n、]/).includes(query.category))&&(!query.status||r.cells[7]===query.status)&&(!query.source||r.cells[6]===query.source));}
 function select(label,items,value,width,onchange){const wrap=node('span','asr-select');wrap.style.width=width+'px';const el=node('select');el.setAttribute('aria-label',label);items.forEach(([value,text])=>el.append(new Option(text,value)));el.value=value;el.onchange=()=>onchange(el.value);wrap.append(el);return wrap;}
 function categories(){return [...new Set(table().rows.flatMap(r=>r.cells[4].split(/[\n、]/)).filter(Boolean))];}
 function edit(row){A.edit(row);const note=A.$('dialogBody').querySelector('.form-note');if(note)note.textContent='沿用已有本地词条表单。修改仅保存到当前浏览器，不写入真实词库。';}
 function batchCategory(){const targets=table().rows.filter(r=>selected.has(r.id));if(!targets.length)return;const form=node('form'),box=A.fieldControl({label:'大类',required:true,controls:[{type:'select'}],options:categories()},'',form);form.append(node('p','form-note','仅修改当前浏览器中已选词条的大类。'),box);A.showDialog('批量修改大类',form,[{label:'取消',run:A.closeDialog},{label:'保存',cls:'primary',run:()=>{if(!form.reportValidity())return;const value=form.querySelector('[data-field]').value;targets.forEach(r=>{r.cells[4]=value;r.extra={...r.extra,'大类':value};});A.persist('批量修改大类',targets.length+' 条');A.closeDialog();render();A.toast('已更新本地词条');}}]);}
 function remove(targets){if(!targets.length)return;A.confirmAction('删除',`将删除 ${targets.length} 条本地记录，删除后可撤销。`,()=>{const before=structuredClone(table().rows);A.getTable().rows=A.getTable().rows.filter(r=>!targets.includes(r));selected.clear();A.persist('删除',targets.length+' 条');render();const body=node('p','',`已删除 ${targets.length} 条本地记录。`);A.showDialog('删除完成',body,[{label:'撤销删除',run:()=>{A.getTable().rows=before;A.persist('撤销删除');A.closeDialog();render();}},{label:'完成',cls:'primary',run:A.closeDialog}]);});}
 function filters(){const form=node('form','asr-filters'),input=node('input','asr-input');input.placeholder='错词 / 正词关键词';input.setAttribute('aria-label','错词或正词关键词');input.value=draft.word;input.oninput=()=>draft.word=input.value;form.append(input,select('大类',[['','全部大类'],...categories().map(x=>[x,x])],draft.category,150,v=>draft.category=v),select('状态',[['','全部状态'],['启用','启用'],['停用','停用']],draft.status,130,v=>draft.status=v),select('来源',[['','全部来源'],...[...new Set(table().rows.map(r=>r.cells[6]).filter(Boolean))].map(x=>[x,x])],draft.source,130,v=>draft.source=v));const search=()=>{query={...draft};selected.clear();render();};form.append(btn('查询',search,'is-blue','search'),btn('重置',()=>{query={word:'',category:'',status:'',source:''};draft={...query};selected.clear();render();},'','reset'));form.onsubmit=e=>{e.preventDefault();search();};return form;}
 function check(label,checked,onchange){const c=node('input','asr-check');c.type='checkbox';c.checked=checked;c.setAttribute('aria-label',label);c.onchange=()=>onchange(c.checked);return c;}
 function render(){
  observer?.disconnect();const data=rows(),visible=data.slice(0,pageSize);document.body.classList.add('admin-asr-content');const root=node('section','asr-page'),header=node('header','asr-heading');header.append(node('h2','','语音纠错词库'));const tools=node('div');tools.append(btn('文件导入',()=>unavailable('文件导入'),'is-teal','upload'),btn('新增词条',()=>edit(),'is-teal','plus'));header.append(tools);root.append(header);
  const tabs=node('nav','asr-tabs');tabs.setAttribute('aria-label','词库页签');for(const label of ['纠错映射','专业词汇','命中对照'])tabs.append(btn(label,()=>label==='纠错映射'?null:unavailable(label),label==='纠错映射'?'selected':''));root.append(tabs,filters());
  const wrap=node('div','asr-table-wrap'),t=node('table','asr-table'),cols=node('colgroup'),head=node('thead'),hr=node('tr');table().headers.forEach((label,i)=>{cols.append(node('col'));const th=node('th','',label);if(!i){const all=check('选择当前页',visible.length>0&&visible.every(r=>selected.has(r.id)),value=>{visible.forEach(r=>value?selected.add(r.id):selected.delete(r.id));render();});all.disabled=!visible.length;all.indeterminate=selected.size>0&&!all.checked;th.append(all);}hr.append(th);});head.append(hr);t.append(cols,head);const body=node('tbody');
  for(const r of visible){const tr=node('tr');r.cells.forEach((value,i)=>{const td=node('td');if(i===0)td.append(check('选择词条 '+r.cells[1],selected.has(r.id),value=>{value?selected.add(r.id):selected.delete(r.id);render();}));else if(i===7){const sw=check('启用 '+r.cells[1],value!=='停用',enabled=>{r.cells[7]=enabled?'启用':'停用';r.extra={...r.extra,'启用':r.cells[7]};A.persist('修改启用状态',r.cells[1]);render();});sw.className='asr-switch';sw.setAttribute('role','switch');td.append(sw);}else if(i===9)td.append(btn('编辑',()=>edit(r),'is-link','edit'),btn('删除',()=>remove([r]),'is-link is-danger','trash'));else if(i===3||i===6)td.append(node('span','asr-tag'+(value==='直接纠正'||i===6?' is-green':''),value));else if(i===4&&value!=='通用'){value.split('\n').filter(Boolean).forEach(term=>td.append(node('span','asr-tag is-blue',term)));}else td.textContent=value;tr.append(td);});body.append(tr);}t.append(body);wrap.append(t);
  if(!visible.length)wrap.append(node('div','asr-empty','暂无数据'));root.append(wrap);const footer=node('footer','asr-footer'),batch=node('div','asr-batch'),category=btn('批量修改大类',batchCategory,'','edit'),removeButton=btn('批量删除',()=>remove(table().rows.filter(r=>selected.has(r.id))),'is-danger is-pale','trash');category.disabled=removeButton.disabled=!selected.size;batch.append(category,removeButton);footer.append(batch);
  const pager=node('div','asr-pagination');pager.append(select('每页条数',[[20,'20条/页'],[50,'50条/页'],[100,'100条/页']],String(pageSize),128,v=>{pageSize=Number(v);selected.clear();render();}));const prev=btn('‹',()=>{});prev.disabled=true;prev.setAttribute('aria-label','上一页');pager.append(prev,btn('1',()=>{},'selected'));const untouched=A.tenant==='yestar-sz'&&!query.word&&!query.category&&!query.status&&!query.source&&table().rows.length===20;if(untouched)for(const n of ['2','3','4','5','6','…','86'])pager.append(btn(n,()=>A.toast('本地仅保留已采首屏词条样本。')));const next=btn('›',()=>A.toast('本地仅保留已采首屏词条样本。'));next.disabled=!untouched;next.setAttribute('aria-label','下一页');pager.append(next,node('span','',`共 ${untouched?1712:data.length} 条`));footer.append(pager);root.append(footer);A.$('app').replaceChildren(root);
  const resize=()=>{const width=Math.round(wrap.clientWidth),base=[52,140,140,170,180,180,110,90,170,160],extra=Math.max(0,width-1392);base[2]+=Math.floor(extra*140/640);base[4]+=Math.floor(extra*180/640);base[5]+=Math.floor(extra*180/640);base[1]+=extra-(base[2]-140)-(base[4]-180)-(base[5]-180);[...cols.children].forEach((c,i)=>c.style.width=base[i]+'px');t.style.width=Math.max(width,1392)+'px';};requestAnimationFrame(resize);observer=new ResizeObserver(resize);observer.observe(wrap);return true;
 }
 A.$('dialog').addEventListener('close',()=>{if(A.model)render();});V.render=()=>render()||previous?.();
})();
